<div class="grid gap-5 xl:grid-cols-3"><section class="card overflow-hidden xl:col-span-2"><div class="overflow-x-auto"><table class="w-full min-w-[650px] text-left text-sm"><thead class="bg-gray-50 text-xs uppercase text-gray-500"><tr><th class="p-3">Check-up date</th><th class="p-3">Diagnosis</th><th class="p-3">Treatment / medicine</th><th class="p-3">Outcome</th><th class="p-3">Remarks</th><th class="p-3">Action</th></tr></thead><tbody class="divide-y divide-gray-100"><?php foreach($records as $r): ?><tr><td class="p-3"><?= esc(format_date($r['checkup_date'])) ?></td><td class="p-3"><?= esc($r['diagnosis']??$r['chief_complaint']??'—') ?></td><td class="p-3"><?= esc($r['treatment']??'—') ?></td><td class="p-3"><?= esc($r['outcome']??'—') ?></td><td class="p-3"><?= esc($r['remarks']??'—') ?></td><td class="p-3"><details><summary class="cursor-pointer text-accent">Edit</summary><form class="mt-2 min-w-64 space-y-2" method="post" action="<?= site_url('children/'.$child['id'].'/checkups/'.$r['id'].'/update') ?>"><?= csrf_field() ?><label class="block text-xs" for="checkup-date-<?= $r['id'] ?>">Check-up date<input class="form-control mt-1" id="checkup-date-<?= $r['id'] ?>" type="date" name="checkup_date" max="<?= date('Y-m-d') ?>" value="<?= esc($r['checkup_date']) ?>" required></label><?php foreach(['chief_complaint'=>'Chief complaint','diagnosis'=>'Diagnosis','findings'=>'Findings','treatment'=>'Treatment / medicine','remarks'=>'Remarks'] as $field=>$label): ?><label class="block text-xs" for="<?= $field ?>-<?= $r['id'] ?>"><?= esc($label) ?><textarea class="form-control mt-1" id="<?= $field ?>-<?= $r['id'] ?>" name="<?= $field ?>"><?= esc($r[$field]??'') ?></textarea></label><?php endforeach ?><label class="block text-xs" for="temp-<?= $r['id'] ?>">Temperature °C<input class="form-control mt-1" id="temp-<?= $r['id'] ?>" name="temperature_c" type="number" step=".1" value="<?= esc($r['temperature_c']??'') ?>"></label><label class="block text-xs" for="weight-<?= $r['id'] ?>">Weight kg<input class="form-control mt-1" id="weight-<?= $r['id'] ?>" name="weight_kg" type="number" step=".1" value="<?= esc($r['weight_kg']??'') ?>"></label><label class="block text-xs" for="follow-up-<?= $r['id'] ?>">Follow-up date<input class="form-control mt-1" id="follow-up-<?= $r['id'] ?>" name="follow_up_date" type="date" value="<?= esc($r['follow_up_date']??'') ?>"></label><label class="block text-xs" for="referral-<?= $r['id'] ?>">Referred to<input class="form-control mt-1" id="referral-<?= $r['id'] ?>" name="referred_to" value="<?= esc($r['referred_to']??'') ?>"></label><label class="block text-xs" for="outcome-<?= $r['id'] ?>">Outcome<select class="form-control mt-1" id="outcome-<?= $r['id'] ?>" name="outcome"><option value="">Select</option><?php foreach(['Recovered','Resolved','Stable','Ongoing','Referred'] as $outcome): ?><option <?= ($r['outcome']??'')===$outcome?'selected':'' ?>><?= $outcome ?></option><?php endforeach ?></select></label><button class="btn-primary">Save changes</button></form></details><details class="mt-2"><summary class="cursor-pointer text-red-700">Delete</summary><form class="mt-2 flex gap-2" method="post" action="<?= site_url('children/'.$child['id'].'/checkups/'.$r['id'].'/delete') ?>"><?= csrf_field() ?><label class="sr-only" for="reason-<?= $r['id'] ?>">Reason</label><input class="form-control" id="reason-<?= $r['id'] ?>" name="reason" required placeholder="Reason"><button class="min-h-11 rounded bg-red-700 px-3 text-white">Confirm</button></form></details></td></tr><?php endforeach ?><?php if(!$records): ?><tr><td colspan="6" class="p-5 text-center text-gray-500">No medical history recorded.</td></tr><?php endif ?></tbody></table></div><div class="p-4"><?= $pager->links() ?></div></section>
<section class="card p-5"><h2 class="text-lg font-semibold">Add Check-up Record</h2><form class="mt-4 space-y-3" method="post" action="<?= site_url('children/'.$child['id'].'/checkups') ?>"><?= csrf_field() ?><?php foreach(['checkup_date'=>'Check-up date','chief_complaint'=>'Chief complaint','diagnosis'=>'Diagnosis','findings'=>'Findings','temperature_c'=>'Temperature (°C)','weight_kg'=>'Weight (kg)','treatment'=>'Treatment / medicine','follow_up_date'=>'Follow-up date','referred_to'=>'Referred to','remarks'=>'Remarks'] as $field=>$label): ?><div><label class="form-label" for="<?= $field ?>"><?= esc($label) ?></label><?php if(in_array($field,['chief_complaint','diagnosis','findings','treatment','remarks'],true)): ?><textarea class="form-control" id="<?= $field ?>" name="<?= $field ?>" rows="2"></textarea><?php else: ?><input class="form-control" id="<?= $field ?>" name="<?= $field ?>" type="<?= str_contains($field,'date')?'date':(in_array($field,['temperature_c','weight_kg'],true)?'number':'text') ?>" <?= in_array($field,['temperature_c','weight_kg'],true)?'step=".1"':'' ?> <?= $field==='checkup_date'?'max="'.date('Y-m-d').'" required':'' ?>><?php endif ?></div><?php endforeach ?><div><label class="form-label" for="outcome">Outcome</label><select class="form-control" id="outcome" name="outcome"><option value="">Select outcome</option><?php foreach(['Recovered','Resolved','Stable','Ongoing','Referred'] as $o): ?><option><?= $o ?></option><?php endforeach ?></select></div><button class="btn-primary w-full">Save Medical Record</button></form></section></div><?= $this->endSection() ?>
